WITH piligrim_dest_list AS ( SELECT DISTINCT dest_id FROM ( VALUES (70346),(808),(83409),(216354),(1585),(217362),(975),(759),(216346),(65815), (247),(307614),(289873),(76480),(204358),(298723),(82558),(75103),(517), (265316),(231),(1529),(879),(217335),(1242),(71642),(93968),(74124),(142), (636),(1136),(520),(669),(1061),(77167),(275),(69526),(802),(196),(1528), (77530),(200347),(305974),(68747),(735),(84848),(197504),(216551),(68705), (1343),(80438),(427),(77687),(73533),(196096),(202212),(711),(78796),(489), (747),(93580),(466),(77705),(68871),(1148),(1459),(361),(471),(70983), (81826),(501),(987),(93189),(76187),(196752),(84832),(74690),(1219), (94515),(1007),(65805),(496),(194482),(94509),(198868),(842),(69475), (74130),(215191),(84310),(1496),(403),(1141),(189),(133),(177),(1351), (70628),(74708),(66007),(198750),(663),(94877),(71756),(1128),(293),(534), (77093),(154),(1001),(70030),(576),(70429),(217),(960),(196420),(134), (205655),(94782),(300439) ) AS x(dest_id) ), Txn_details AS ( SELECT DISTINCT rb_user_id FROM "transaction"."bus_ticket_events" t WHERE date_of_issue >= TIMESTAMP '2025-02-28 18:30:00' AND date_of_issue < TIMESTAMP '2026-02-28 18:30:00' AND country_code = 'IND' AND business_unit = 'REDBUS_IN' AND event_class = 2 AND event_type = 101 AND tin IS NOT NULL AND tin NOT IN ('', 'null') AND rb_user_id >0 ), srp AS ( SELECT s.rb_user_id, coalesce(s.os, s.channel) saleschannel, s.src_id, s.dest_id, s.mri_session_id, CAST(DATE_TRUNC('day', at_timezone(s.__time, 'Asia/Kolkata')) AS DATE) AS doi, ROW_NUMBER() OVER (PARTITION BY s.rb_user_id ORDER BY s.__time DESC) AS last_search FROM "user_interaction"."search_route_details" s INNER JOIN piligrim_dest_list p ON s.dest_id = p.dest_id WHERE __time >= TIMESTAMP '2025-11-30 18:30:00' AND __time < TIMESTAMP '2026-02-28 18:30:00' AND UPPER(user_type) = 'NEW' AND s.src_id = 122 AND rb_user_id >0 AND rb_user_id NOT IN (SELECT rb_user_id FROM Txn_details) AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND country = 'IND' ), eligible_users AS ( SELECT rb_user_id, COUNT(DISTINCT mri_session_id) search_sessions FROM srp GROUP BY 1 ) SELECT s.rb_user_id, s.saleschannel, ud.fullname, ud.hash_mobile, ud.hash_email, ud.gender, CAST(s.src_id AS VARCHAR) ||'-'|| CAST(s.dest_id AS VARCHAR) AS last_sd_id, (src.location_name ||'-'|| dest.location_name) AS last_route, s.doi AS last_search_date, bu.search_sessions pilgrim_routes_search_count FROM srp s LEFT JOIN "lis"."config_locations" src ON s.src_id = src.id LEFT JOIN "lis"."config_locations" dest ON s.dest_id = dest.id INNER JOIN eligible_users bu ON bu.rb_user_id = s.rb_user_id AND search_sessions BETWEEN 3 AND 20 LEFT JOIN "svoc"."svoc_booker" ud ON CAST(s.rb_user_id AS VARCHAR) = ud.rb_userid WHERE last_search = 1 ORDER BY s.doi DESC LIMIT 10000
